import type { Plugin } from "../../kernel/types";

export default {
  id: "factor-base",
  name: "Factor Base",
  version: "1.0.0",
  onLoad(ctx) {
    ctx.register({
      kind: "service",
      service: {
        id: "factor",
        instance: { value: 7 },
      },
    });
  },
} satisfies Plugin;

